/**
 * Generate element id for node
 * @param {String} nodeType
 * @param {number} length
 * @param {String} platformPrefix
 * @returns {String}
 */
export function generateElementId(nodeType, length = 8, platformPrefix = 'tao') {
    const allLowerAlpha = [...'abcdefghijklmnopqrstuvwxyz'];
    const allNumbers = [...'0123456789'];
    const base = [...allNumbers, ...allLowerAlpha];

    const hash = [...Array(length)].map(() => base[Math.floor(Math.random() * base.length)]).join('');
    return `${platformPrefix}-${nodeType}-${hash}`;
}

/**
 * Gets keyboard-focusable elements within a specified element
 * Adapted from https://github.com/zellwk/zellwk.com/blob/master/src/posts/2020-01-29-getting-focusable-elements.md
 * @param {HTMLElement} [element=document] element
 * @returns {Array}
 */
export function getKeyboardFocusableElements(element = document) {
    return [...element.querySelectorAll('a, button, input:not([type="hidden"]), textarea, select, details, [tabindex]')]
        .filter(el => el.getAttribute('tabindex') !== '-1')
        .filter(el => !el.hasAttribute('disabled'));
}

/**
 * Tells if an element is rendered as right-to-left
 * @param {DOMElement} element
 * @returns {Boolean}
 */
export function isRTLElement(element) {
    return window.getComputedStyle(element).getPropertyValue('direction') === 'rtl';
}

/**
 * Get pointer coordinates from mousedown/mousemove/mouseup/touchstart/touchmove/touchend event
 * @param {MouseEvent|TouchEvent} e
 * @returns {Object} coordinates object: {x, y}
 */
export function getPointerEventCoords(e) {
    if (e.changedTouches) {
        e = e.changedTouches[0];
    }
    return { x: e.clientX, y: e.clientY };
}
